changeSet.sql:
ALTER TABLE court_schedule ADD COLUMN IF NOT EXISTS is_week_commencing BOOLEAN NOT NULL DEFAULT false;

DROP INDEX IF EXISTS court_act_business_date_session_idx_am;
DROP INDEX IF EXISTS court_act_business_date_session_idx_pm;

CREATE UNIQUE INDEX IF NOT EXISTS court_act_business_date_session_idx_am ON
court_schedule(oucode, court_room_id, rota_business_type,
session_start, (REPLACE(court_session,'AD'::text,'AM'::text))
text_ops, is_draft, is_week_commencing) where active is TRUE;

CREATE UNIQUE INDEX IF NOT EXISTS court_act_business_date_session_idx_pm ON
court_schedule(oucode, court_room_id, rota_business_type,
session_start, (REPLACE(court_session,'AD'::text,'PM'::text))
text_ops, is_draft, is_week_commencing) where active is TRUE;

rollback.sql:
